"""Pure, read-only comparison of *selected* Docker inspect metadata to policy.

Metadata parity is not backup, source reproducibility, migration or smoke proof.
Never inspect/emit process environment, Docker labels or raw application logs.
"""
from __future__ import annotations
import ipaddress
import json
from typing import Any


def parse_targeted_inspect(output: str) -> dict:
    """Strict JSON record generated by a targeted docker-inspect template."""
    if not isinstance(output, str):
        raise ValueError("Docker inspect output is not text")
    parts = output.splitlines()
    if len(parts) != 15:
        raise ValueError("unexpected targeted inspect field count")
    p = [json.loads(line) for line in parts]
    # Reject malformed projected values instead of interpreting strings such
    # as "true" as booleans or "ALL" as a capability list. No raw values go
    # into errors, reports, or logs.
    def is_text(value):
        return isinstance(value, str)
    def text_list_or_null(value):
        return value is None or (isinstance(value, list)
                                 and all(is_text(x) for x in value))
    fields = (
        (0, is_text), (1, is_text), (2, lambda x: type(x) is bool),
        (3, is_text), (4, lambda x: type(x) is int and x >= 0),
        (5, lambda x: isinstance(x, list) and all(isinstance(m, dict)
                                                   and is_text(m.get("Type"))
                                                   and is_text(m.get("Destination"))
                                                   and type(m.get("RW")) is bool
                                                   for m in x)),
        (6, lambda x: x is None or isinstance(x, dict)),
        (7, lambda x: x is None or isinstance(x, dict)),
        (8, lambda x: type(x) is bool), (9, lambda x: type(x) is bool),
        (10, text_list_or_null), (11, text_list_or_null),
        (12, text_list_or_null), (13, is_text), (14, is_text),
    )
    for index, predicate in fields:
        if not predicate(p[index]):
            raise ValueError(f"invalid type or missing Docker metadata field {index}")
    for mount in p[5]:
        if mount["Type"] == "bind" and not is_text(mount.get("Source")):
            raise ValueError("invalid Docker bind source")
        if mount["Type"] == "volume" and not is_text(mount.get("Name")):
            raise ValueError("invalid Docker volume identity")
    for value in (p[6] or {}).values():
        if value is not None and (
            not isinstance(value, list)
            or not all(isinstance(v, dict)
                       and is_text(v.get("HostIp"))
                       and is_text(v.get("HostPort")) for v in value)
        ):
            raise ValueError("invalid Docker port binding metadata")
    return {
        "image_id": p[0], "configured_image": p[1],
        "running": p[2], "health": p[3], "restart_count": p[4],
        "mounts": p[5], "ports": p[6] or {}, "networks": p[7] or {},
        "privileged": p[8], "readonly_root": p[9],
        "cap_add": p[10] or [], "cap_drop": p[11] or [],
        "security_opt": p[12] or [], "user": p[13], "network_mode": p[14]
    }


# Docker Go template. Each json field is encoded separately; no Env, health
# probe output, container labels, tokens, or raw Docker inspect record.
INSPECT_TEMPLATE = "\n".join([
    "{{json .Image}}", "{{json .Config.Image}}",
    "{{json .State.Running}}",
    "{{with .State.Health}}{{json .Status}}{{else}}{{json \"no_healthcheck\"}}{{end}}",
    "{{json .RestartCount}}", "{{json .Mounts}}",
    "{{json .NetworkSettings.Ports}}",
    "{{json .NetworkSettings.Networks}}",
    "{{json .HostConfig.Privileged}}",
    "{{json .HostConfig.ReadonlyRootfs}}",
    "{{json .HostConfig.CapAdd}}",
    "{{json .HostConfig.CapDrop}}",
    "{{json .HostConfig.SecurityOpt}}",
    "{{json .Config.User}}",
    "{{json .HostConfig.NetworkMode}}"
])


def observed_ports(snapshot: dict) -> set[str]:
    ports: set[str] = set()
    for destination, bindings in (snapshot.get("ports") or {}).items():
        for item in bindings or []:
            address = item.get("HostIp") or "0.0.0.0"
            if ":" in address:
                address = f"[{address}]"
            ports.add(f"{address}:{item.get('HostPort')}->{destination}")
    return ports


def _private_binding(port: str) -> bool:
    host = port.split("->", 1)[0].rsplit(":", 1)[0].strip("[]")
    try:
        addr = ipaddress.ip_address(host)
        return (not addr.is_unspecified and not addr.is_multicast
                and (addr.is_private or addr.is_loopback))
    except ValueError:
        return False


def contract_differences(service: dict, snapshots: list[dict]) -> list[str]:
    """Return *descriptive* drift/unverified reasons for policy-vs-runtime metadata.

    Never set an update-ready state based only on these comparisons.
    """
    issues: list[str] = []
    if not snapshots:
        return ["runtime identity not inspected"]
    if any(s.get("running") is not True for s in snapshots):
        issues.append("one or more Compose containers not running")
    image = service.get("image", {})
    # Multi-image groups may contain images for subordinate services. The
    # policy's image identity is required for at least one declared component.
    expected_id = image.get("immutable_identity")
    observed_ids = {s.get("image_id") for s in snapshots}
    if expected_id and expected_id not in observed_ids:
        issues.append("declared primary immutable image identity differs from runtime")
    if not expected_id:
        issues.append("declared immutable image identity unverified")
    expected_ref = image.get("runtime_reference")
    if expected_ref and expected_ref not in {s.get("configured_image") for s in snapshots}:
        issues.append("configured primary image reference differs from policy")
    mounts = [m for s in snapshots for m in (s.get("mounts") or [])]
    state = service.get("state_contract", {})
    expected = []
    for bind in state.get("binds", []):
        if isinstance(bind, dict):
            expected.append(("bind", bind.get("source"), bind.get("target"),
                             bind.get("mode") == "rw"))
    for volume in state.get("named_volumes", []):
        if isinstance(volume, dict):
            expected.append(("volume", volume.get("name"), volume.get("target"), True))
    def match(m: dict, kind: str, source: str, target: str, rw: bool) -> bool:
        return (m.get("Type") == kind
                and (m.get("Source") if kind == "bind" else m.get("Name")) == source
                and m.get("Destination") == target and m.get("RW") is rw)
    for kind, source, target, rw in expected:
        if not any(match(m, kind, source, target, rw) for m in mounts):
            issues.append(f"mount identity/mode mismatch at declared target {target}")
    # Additional mounts are never waved through as harmless.
    for mount in mounts:
        if mount.get("Type") not in ("bind", "volume"):
            issues.append("unexpected mount type (inspection required)")
        elif not any(match(mount, *item) for item in expected):
            issues.append("undeclared runtime mount present")
    topology = service.get("topology", {})
    all_ports = set().union(*(observed_ports(s) for s in snapshots))
    if set(topology.get("ports", [])) != all_ports:
        issues.append("published port bindings differ from policy")
    all_networks = set().union(*(set((s.get("networks") or {}).keys()) for s in snapshots))
    if set(topology.get("networks", [])) != all_networks:
        issues.append("Docker network names differ from policy")
    for snap in snapshots:
        mode = snap.get("network_mode")
        if not isinstance(mode, str) or not mode:
            issues.append("network mode evidence unavailable")
        elif mode in {"host", "none"} or mode.startswith("container:"):
            issues.append(f"non-standard network_mode {mode!r} requires explicit review")
        declared_mode = topology.get("network_mode")
        if declared_mode is not None and mode != declared_mode:
            issues.append("Docker network mode differs from policy")
    required_health = service.get("health", {}).get("docker_expectation")
    for snap in snapshots:
        if required_health in ("healthy", "no_healthcheck") and snap.get("health") != required_health:
            issues.append(f"Docker health expectation differs for {snap.get('service')}")
        restart_count = snap.get("restart_count")
        if type(restart_count) is not int:
            issues.append("restart stability evidence unavailable")
        elif restart_count != 0:
            issues.append("container has a nonzero restart history; stability requires time-window verification")
        if snap.get("privileged") is True:
            issues.append("privileged runtime observed (requires explicit review)")
        if snap.get("cap_add"):
            issues.append("added Linux capabilities observed (requires explicit review)")
    security = topology.get("security_invariants") or []
    for invariant in security:
        if invariant == "read_only_root" and any(s.get("readonly_root") is not True for s in snapshots):
            issues.append("readonly root filesystem policy mismatch")
        elif invariant == "no_new_privileges" and any(
            not any(str(x).lower() in ("no-new-privileges", "no-new-privileges:true", "no-new-privileges= true", "no-new-privileges=true") for x in (s.get("security_opt") or []))
            for s in snapshots
        ):
            issues.append("no-new-privileges policy mismatch")
        elif invariant == "cap_drop_all" and any(
            "ALL" not in (s.get("cap_drop") or []) for s in snapshots
        ):
            issues.append("cap-drop ALL policy mismatch")
        elif invariant == "read_only_docker_socket":
            if not any(
                m.get("Type") == "bind"
                and m.get("Source") == "/var/run/docker.sock"
                and m.get("Destination") == "/var/run/docker.sock"
                and m.get("RW") is False
                for m in mounts
            ):
                issues.append("read-only docker socket identity mismatch")
        elif invariant == "lan_only_binding" and any(not _private_binding(p) for p in all_ports):
            issues.append("non-private published port present")
        elif isinstance(invariant, str) and invariant.startswith("user_"):
            # Portable numeric user invariant, e.g. user_1000_1000.
            uid_gid = invariant[5:].split("_")
            if len(uid_gid) != 2 or not all(v.isdigit() for v in uid_gid):
                issues.append("unsupported user identity policy invariant")
            elif any(s.get("user") != ":".join(uid_gid) for s in snapshots):
                issues.append("container user identity policy mismatch")
        elif invariant not in {
            "read_only_root", "no_new_privileges", "cap_drop_all",
            "read_only_docker_socket", "lan_only_binding"
        }:
            issues.append(f"unsupported security invariant: {invariant}")
    return list(dict.fromkeys(issues))
